def transform(grid):
    g=[row[:] for row in grid]; H=len(g); W=len(g[0])
    fives=[(r,c) for r in range(H) for c in range(W) if g[r][c]==5]
    from collections import deque
    shape=set()
    for r in range(H):
        for c in range(W):
            if g[r][c] not in (0,5) and (r,c) not in shape:
                q=deque([(r,c)]); comp={(r,c)}
                while q:
                    a,b=q.popleft()
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and g[x][y] not in (0,5) and (x,y) not in comp:
                                comp.add((x,y)); q.append((x,y))
                if len(comp)>len(shape): shape=comp
    def dist(p,q): return abs(p[0]-q[0])+abs(p[1]-q[1])
    a5=min(fives,key=lambda p: min(dist(p,s) for s in shape))
    targets=[p for p in fives if p!=a5]
    adj=[s for s in shape if dist(a5,s)==1]
    anchor=a5 if len(adj)>=2 else adj[0]
    for t in targets:
        dr,dc=t[0]-anchor[0],t[1]-anchor[1]
        for (r,c) in shape:
            if (r,c)==anchor: continue
            g[r+dr][c+dc]=g[r][c]
        g[t[0]][t[1]]=0
    return g

